package net.officefloor.hq.app.history;

import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/** Reads a sheet as it stood at the end of a date from its history (see {@link HistoryListener}): every
 * change made while the sheet's today was on or before that date counts, every later change does not. */
@Service
public class SheetHistory {

    private final JdbcTemplate jdbc;

    public SheetHistory(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet as it stood at the end of {@code date}, that date standing in for its today. */
    @Transactional(propagation = Propagation.MANDATORY)
    public SheetAsOf asOf(String sheetId, LocalDate date) {
        return asOf(sheetId, date, new LinkedHashSet<>(List.of(sheetId)));
    }

    /** The sheet as it stood at the end of {@code date}, with its parents' rates as they stood then;
     * {@code chain} holds the sheet and the sheets below it whose parents are being read. */
    private SheetAsOf asOf(String sheetId, LocalDate date, Set<String> chain) {
        Map<String, String> latest = new LinkedHashMap<>();
        LocalDate upTo = date;
        if (chain.size() > 1) {
            // A parent started on a later date than the day read stood then as at the end of its first day.
            LocalDate first = jdbc.query("SELECT MIN(made_on) FROM sheet_history WHERE sheet_id = ?",
                    rs -> rs.next() && rs.getDate(1) != null ? rs.getDate(1).toLocalDate() : null, sheetId);
            if (first != null && first.isAfter(date)) upTo = first;
        }
        jdbc.query("SELECT entity, entity_id, state FROM sheet_history WHERE sheet_id = ? AND made_on <= ? ORDER BY id",
                rs -> {
                    latest.put(rs.getString(1) + ":" + rs.getString(2), rs.getString(3));
                }, sheetId, Date.valueOf(upTo));
        Map<String, Class<?>> types = new HashMap<>();
        HistoryListener.KEPT.forEach((type, name) -> types.put(name, type));
        Sheet sheet = null;
    public boolean archived() {
        return sheet != null && sheet.isArchived();
    }

    /** The number of the sheet's last settle batch then; null when it had had none. */
    public Integer lastSettleBatch() {
        return sheet == null ? null : sheet.getLastSettleBatch();
    }

    /** The policy date as it was set then; null when it was the sheet's today. */
    public LocalDate policyDate() {
        return sheet == null ? null : sheet.getPolicyDate();
    }

    /** The period numbering from then; null when it was off. */
    public LocalDate periodNumberingFrom() {
        return sheet == null ? null : sheet.getPeriodNumberingFrom();
    }

    /** The id of the sheet's parent then; null when it had none. */
    public String parentId() {
        return sheet == null ? null : sheet.getParentId();
    }

    /** The sheet's rates then, then its parent's as they stood then, and so on up to
     * {@link RateChain#LEVELS_UP} levels up: each by grade, then by from-date. */
    public List<List<Rate>> rateLevels() {
        List<List<Rate>> levels = new ArrayList<>();
        levels.add(rates);
        levels.addAll(inherited);
        return levels;
    }

-- The sheet's parent: the sheet whose rates (then its parent's, up to three levels up) are used for a
-- grade and date that have no rate in force on this sheet; null when there is none. Not dated.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(100);
    }

    public BigDecimal getAlertThreshold() {
        return alertThreshold;
    }

    public void setAlertThreshold(BigDecimal alertThreshold) {
        this.alertThreshold = alertThreshold;
    }

    public String getParentId() {
        return parentId;
    }

    public void setParentId(String parentId) {
        this.parentId = parentId;
    }

    /** The date a claim left without a date is dated: the entry date when it is set, else the sheet's today. */
    public LocalDate entryDateInForce() {
        return entryDate == null ? today : entryDate;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    public Integer getLastSettleBatch() {
        return lastSettleBatch;
    }

    /** Start the sheet's next settle batch, returning its number. */
    public int nextSettleBatch() {
        lastSettleBatch = lastSettleBatch == null ? 1 : lastSettleBatch + 1;
        return lastSettleBatch;
    }
}

